action.command:
node -e "
const fs = require('fs');
const path = process.env.KIRO_FILE_PATH || process.argv[2];
if (!path) process.exit(0);
const src = fs.readFileSync(path, 'utf8');
// Strip string/template literal contents before checking
const stripped = src
  .replace(/\`[^\`]*\`/g, '\"\"')
  .replace(/\"(?:[^\"\\\\]|\\\\.)*\"/g, '\"\"')
  .replace(/'(?:[^'\\\\]|\\\\.)*'/g, \"''\");
// Check for middle dot (U+00B7) or non-ASCII
const badChars = [...stripped].filter(c => c === '\\u00b7' || c.charCodeAt(0) > 126 || c.charCodeAt(0) < 32 &amp;&amp; c !== '\\n' &amp;&amp; c !== '\\r' &amp;&amp; c !== '\\t');
if (badChars.length > 0) {
  const chars = [...new Set(badChars)].map(c => 'U+' + c.charCodeAt(0).toString(16).toUpperCase().padStart(4,'0'));
  process.stderr.write('ASCII guard: non-ASCII or middle-dot found in ' + path + ': ' + chars.join(', ') + '\\n');
  process.exit(2);
}
process.exit(0);
"
